   281  /* Create descriptor for ELF file in memory.  */
   282  static Elf *
   283  file_read_elf (int fildes, void *map_address, unsigned char *e_ident,
   284                 int64_t offset, size_t maxsize, Elf_Cmd cmd, Elf *parent)
   285  {
   286    /* Verify the binary is of the class we can handle.  */
   287    if (unlikely ((e_ident[EI_CLASS] != ELFCLASS32
   288                   && e_ident[EI_CLASS] != ELFCLASS64)
   289                  /* We also can only handle two encodings.  */
   290                  || (e_ident[EI_DATA] != ELFDATA2LSB
   291                      && e_ident[EI_DATA] != ELFDATA2MSB)))
   292      {
   293        /* Cannot handle this.  */
   294        __libelf_seterrno (ELF_E_INVALID_ELF);
   295        return NULL;
   296      }
   297
   298    /* Determine the number of sections.  Returns -1 and sets libelf errno
   299       if the file handle or elf file is invalid.  Returns zero if there
   300       are no section headers (or they cannot be read).  */
   301    size_t scncnt = get_shnum (map_address, e_ident, fildes, offset, maxsize);
   302    if (scncnt == (size_t) -1l)
   303      /* Could not determine the number of sections.  */
   304      return NULL;
   305
   306    /* Check for too many sections.  */
   307    if (e_ident[EI_CLASS] == ELFCLASS32)
   308      {
   309        if (scncnt > SIZE_MAX / (sizeof (Elf_Scn) + sizeof (Elf32_Shdr)))
   310          {
   311            __libelf_seterrno (ELF_E_INVALID_ELF);
   312            return NULL;
   313          }
   314      }
   315    else if (scncnt > SIZE_MAX / (sizeof (Elf_Scn) + sizeof (Elf64_Shdr)))
   316      {
   317        __libelf_seterrno (ELF_E_INVALID_ELF);
   318        return NULL;
   319      }
   320
   321    /* We can now allocate the memory.  Even if there are no section headers,
   322       we allocate space for a zeroth section in case we need it later.  */
   323    const size_t scnmax = (scncnt ?: (cmd == ELF_C_RDWR || cmd == ELF_C_RDWR_MMAP)
   324                           ? 1 : 0);
   325    Elf *elf = allocate_elf (fildes, map_address, offset, maxsize, cmd, parent,
   326                             ELF_K_ELF, scnmax * sizeof (Elf_Scn));
   327    if (elf == NULL)
   328      /* Not enough memory.  allocate_elf will have set libelf errno.  */
   329      return NULL;
   330
   331    assert ((unsigned int) scncnt == scncnt);
   332    assert (offsetof (struct Elf, state.elf32.scns)
   333            == offsetof (struct Elf, state.elf64.scns));
   334    elf->state.elf32.scns.cnt = scncnt;
   335    elf->state.elf32.scns.max = scnmax;
   336
   337    /* Some more or less arbitrary value.  */
   338    elf->state.elf.scnincr = 10;
   339
   340    /* Make the class easily available.  */
   341    elf->class = e_ident[EI_CLASS];
   342
   343    if (e_ident[EI_CLASS] == ELFCLASS32)
   344      {
   345        /* This pointer might not be directly usable if the alignment is
   346           not sufficient for the architecture.  */
   347        Elf32_Ehdr *ehdr = (Elf32_Ehdr *) ((char *) map_address + offset);
   348
   349        /* This is a 32-bit binary.  */
   350        if (map_address != NULL && e_ident[EI_DATA] == MY_ELFDATA
   351            && (ALLOW_UNALIGNED
   352                || (((uintptr_t) ehdr) & (__alignof__ (Elf32_Ehdr) - 1)) == 0))
   353          {
   354            /* We can use the mmapped memory.  */
   355            elf->state.elf32.ehdr = ehdr;
   356          }
   357        else
   358          {
   359            /* Copy the ELF header.  */
   360            elf->state.elf32.ehdr = memcpy (&elf->state.elf32.ehdr_mem, e_ident,
   361                                            sizeof (Elf32_Ehdr));
   362
   363            if (e_ident[EI_DATA] != MY_ELFDATA)
   364              {
   365                CONVERT (elf->state.elf32.ehdr_mem.e_type);
   366                CONVERT (elf->state.elf32.ehdr_mem.e_machine);
   367                CONVERT (elf->state.elf32.ehdr_mem.e_version);
   368                CONVERT (elf->state.elf32.ehdr_mem.e_entry);
   369                CONVERT (elf->state.elf32.ehdr_mem.e_phoff);
   370                CONVERT (elf->state.elf32.ehdr_mem.e_shoff);
   371                CONVERT (elf->state.elf32.ehdr_mem.e_flags);
   372                CONVERT (elf->state.elf32.ehdr_mem.e_ehsize);
   373                CONVERT (elf->state.elf32.ehdr_mem.e_phentsize);
   374                CONVERT (elf->state.elf32.ehdr_mem.e_phnum);
   375                CONVERT (elf->state.elf32.ehdr_mem.e_shentsize);
   376                CONVERT (elf->state.elf32.ehdr_mem.e_shnum);
   377                CONVERT (elf->state.elf32.ehdr_mem.e_shstrndx);
   378              }
   379          }
   380
   381        /* Don't precache the phdr pointer here.
   382           elf32_getphdr will validate it against the size when asked.  */
   383
   384        Elf32_Off e_shoff = elf->state.elf32.ehdr->e_shoff;
   385        if (map_address != NULL && e_ident[EI_DATA] == MY_ELFDATA
   386            && cmd != ELF_C_READ_MMAP /* We need a copy to be able to write.  */
   387            && (ALLOW_UNALIGNED
   388                || ((((uintptr_t) ehdr + e_shoff)
   389                     & (__alignof__ (Elf32_Shdr) - 1)) == 0)))
   390          {
   391            if (unlikely (scncnt > 0 && e_shoff >= maxsize)
   392                || unlikely (maxsize - e_shoff
   393                             < scncnt * sizeof (Elf32_Shdr)))
   394              {
   395              free_and_out:
   396                free (elf);
   397                __libelf_seterrno (ELF_E_INVALID_ELF);
   398                return NULL;
   399              }
   400
   401            if (scncnt > 0)
   402              elf->state.elf32.shdr
   403                = (Elf32_Shdr *) ((char *) ehdr + e_shoff);
   404
   405            for (size_t cnt = 0; cnt < scncnt; ++cnt)
   406              {
   407                elf->state.elf32.scns.data[cnt].index = cnt;
   408                elf->state.elf32.scns.data[cnt].elf = elf;
   409                elf->state.elf32.scns.data[cnt].shdr.e32 =
   410                  &elf->state.elf32.shdr[cnt];
   411                if (likely (elf->state.elf32.shdr[cnt].sh_offset < maxsize)
   412                    && likely (elf->state.elf32.shdr[cnt].sh_size
   413                               <= maxsize - elf->state.elf32.shdr[cnt].sh_offset))
   414                  elf->state.elf32.scns.data[cnt].rawdata_base =
   415                    elf->state.elf32.scns.data[cnt].data_base =
   416                    ((char *) map_address + offset
   417                     + elf->state.elf32.shdr[cnt].sh_offset);
   418                elf->state.elf32.scns.data[cnt].list = &elf->state.elf32.scns;
