    41  Elf_Scn *
    42  elf_nextscn (Elf *elf, Elf_Scn *scn)
    43  {
    44    Elf_ScnList *list;
    45    Elf_Scn *result = NULL;
    46
    47    if (elf == NULL)
    48      return NULL;
    49
    50    rwlock_rdlock (elf->lock);
    51
    52    if (scn == NULL)
    53      {
    54        /* If no section handle is given return the first (not 0th) section.
    55           Set scn to the 0th section and perform nextscn.  */
    56        if (elf->class == ELFCLASS32
    57             || (offsetof (Elf, state.elf32.scns)
    58                 == offsetof (Elf, state.elf64.scns)))
    59          list = &elf->state.elf32.scns;
    60        else
    61          list = &elf->state.elf64.scns;
    62
    63        scn = &list->data[0];
    64      }
    65    else
    66      list = scn->list;
    67
    68    if (scn + 1 < &list->data[list->cnt])
    69      result = scn + 1;
    70    else if (scn + 1 == &list->data[list->max]
    71             && (list = list->next) != NULL)
    72      {
    73        /* If there is another element in the section list it must
    74           have at least one entry.  */
    75        assert (list->cnt > 0);
    76        result = &list->data[0];
    77      }
    78
    79    rwlock_unlock (elf->lock);
    80
    81    return result;
    82  }
